import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Image / Aspect Ratio · Lazer DS Starter Kit
 * Figma: Components page, Image / Aspect Ratio set. Ratio is locked; the picture fills and crops.
 * With no src it shows the grey ratio placeholder, as in the kit.
 */
export type Ratio = "1:1" | "4:5" | "3:2" | "2:1" | "16:9" | "21:9" | "3:4"

export interface AspectImageProps extends React.HTMLAttributes<HTMLDivElement> {
  ratio?: Ratio
  src?: string
  alt?: string
}

export function AspectImage({ ratio = "3:2", src, alt = "", className, ...props }: AspectImageProps) {
  const [w, h] = ratio.split(":").map(Number)
  return (
    <div
      data-slot="aspect-image"
      data-ratio={ratio}
      style={{ aspectRatio: `${w} / ${h}` }}
      className={cn(
        "relative w-full overflow-hidden rounded-[var(--component-image-radius)] bg-[var(--component-image-background)]",
        className
      )}
      {...props}
    >
      {src ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={src} alt={alt} className="absolute inset-0 size-full object-cover" />
      ) : (
        <span className="lz-label-ui absolute inset-0 grid place-items-center text-[var(--text-muted)]">{ratio}</span>
      )}
    </div>
  )
}
